        public static Tweak ById(string id)
        {
            List<Tweak> all = All();
            for (int i = 0; i < all.Count; i++)
                if (string.Equals(all[i].Id, id, StringComparison.Ordinal)) return all[i];
            return null;
        }

        /// <summary>Tweaks of one group in display order.</summary>
        public static List<Tweak> Group(string group)
        {
            List<Tweak> list = new List<Tweak>();
            List<Tweak> all = All();
            for (int i = 0; i < all.Count; i++)
                if (string.Equals(all[i].Group, group, StringComparison.Ordinal)) list.Add(all[i]);
            return list;
        }

        public static string GroupTitle(string group)
        {
            if (group == "essential") return L.T("Essential Tweaks");
            if (group == "advanced") return L.T("Advanced Tweaks - CAUTION");
            if (group == "prefs") return L.T("Customize Preferences");
            if (group == "performance") return L.T("Performance Plans - NOT FOR LAPTOPS");
            return group;
        }
